const std=@import("std"); const vaxis=@import("vaxis"); const allocator=std.heap.page_allocator; const Item=struct{ text:[]const u8 };
pub fn main() !void { var screen=try vaxis.Screen.init(allocator,.{.cols=8,.rows=3,.x_pixel=0,.y_pixel=0}); const win=vaxis.Window{.screen=&screen,.width=8,.height=3,.x_off=0,.y_off=0,.parent_x_off=0,.parent_y_off=0}; var ctx=vaxis.widgets.Table.TableContext{.selected_bg=.default,.active_bg=.default}; try vaxis.widgets.Table.drawTable(allocator,win,@as([]const Item,&.{.{.text="a"}}),&ctx); }
